INSERT INTO `exam_submissions` VALUES (33, b'1', 61, '2025-11-28 15:28:25.964967', '考试成绩已发布', '{\"content\": \"考试作答：\n\n【单选题】\n1.B 2.A 3.C 4.D 5.B 6.A 7.C 8.D 9.A 10.B\n\n【多选题】\n1.ABD 2.ACD 3.BC 4.ABCD 5.AD\n\n【简答题】\n1. 面向对象的三大特性：\n   - 封装：将数据和操作封装在类中\n   - 继承：子类继承父类的属性和方法\n   - 多态：同一接口的不同实现\n\n2. SQL优化方法：\n   - 使用索引\n   - 避免SELECT *\n   - 合理使用JOIN\"}', 140, 3, 13);
INSERT INTO `exam_submissions` VALUES (34, b'1', 10, '2025-11-28 15:34:25.975800', '考试成绩已发布', '{\"content\": \"我的考试答案：\n\n一、基础知识（40分）\n1. 操作系统的主要功能包括：进程管理、内存管理、文件管理、设备管理。\n2. TCP三次握手过程：SYN -> SYN+ACK -> ACK\n3. HTTP状态码：200成功，404未找到，500服务器错误\n\n二、实践题（60分）\n设计了一个简单的学生管理系统，包含以下功能：\n- 学生信息的增删改查\n- 成绩录入和统计\n- 数据导出功能\n\n使用Spring Boot + MyBatis + MySQL实现。\"}', 79, 3, 74);
INSERT INTO `exam_submissions` VALUES (35, b'1', 85, '2025-11-28 16:14:25.987419', '考试成绩已发布', '{\"content\": \"这是我的考试答案。\n\n一、选择题答案：\n1. A  2. B  3. C  4. D  5. A\n6. B  7. C  8. A  9. D  10. B\n\n二、填空题答案：\n1. 数据结构\n2. 算法复杂度\n3. 二叉树\n4. 哈希表\n5. 递归\n\n三、简答题：\n1. 数据结构是计算机存储、组织数据的方式，它是指相互之间存在一种或多种特定关系的数据元素的集合。\n\n2. 时间复杂度是衡量算法执行时间随输入规模增长的变化趋势，常用大O表示法。\"}', 174, 3, 58);
INSERT INTO `exam_submissions` VALUES (36, b'1', 99, '2025-11-28 15:53:25.998422', '考试成绩已发布', '{\"content\": \"考试答案提交：\n\n第一部分 - 选择题（每题2分）\n1-5: ABCDA\n6-10: BCDAB\n\n第二部分 - 判断题（每题1分）\n1. 对  2. 错  3. 对  4. 对  5. 错\n\n第三部分 - 编程题\n```python\ndef bubble_sort(arr):\n    n = len(arr)\n    for i in range(n):\n        for j in range(0, n-i-1):\n            if arr[j] > arr[j+1]:\n                arr[j], arr[j+1] = arr[j+1], arr[j]\n    return arr\n```\n\n以上是我的全部答案。\"}', 80, 3, 199);
INSERT INTO `exam_submissions` VALUES (37, b'1', 77, '2025-11-28 16:20:26.012418', '考试成绩已发布', '{\"content\": \"期末考试答卷\n\n一、名词解释（20分）\n1. 栈：一种后进先出(LIFO)的数据结构\n2. 队列：一种先进先出(FIFO)的数据结构\n3. 链表：由节点组成的线性数据结构\n4. 图：由顶点和边组成的非线性数据结构\n\n二、计算题（30分）\n1. 二叉树遍历结果：\n   前序：A B D E C F\n   中序：D B E A F C\n   后序：D E B F C A\n\n三、论述题（50分）\n详细阐述了数据库索引的原理和优化策略...\"}', 81, 3, 42);
INSERT INTO `exam_submissions` VALUES (38, b'1', 92, '2025-11-28 15:42:26.025023', '考试成绩已发布', '{\"content\": \"考试作答：\n\n【单选题】\n1.B 2.A 3.C 4.D 5.B 6.A 7.C 8.D 9.A 10.B\n\n【多选题】\n1.ABD 2.ACD 3.BC 4.ABCD 5.AD\n\n【简答题】\n1. 面向对象的三大特性：\n   - 封装：将数据和操作封装在类中\n   - 继承：子类继承父类的属性和方法\n   - 多态：同一接口的不同实现\n\n2. SQL优化方法：\n   - 使用索引\n   - 避免SELECT *\n   - 合理使用JOIN\"}', 60, 3, 109);
