INSERT INTO `exam_submissions` VALUES (69, b'1', 66, '2025-11-28 16:55:26.449507', '考试成绩已发布', '{\"content\": \"我的考试答案：\n\n一、基础知识（40分）\n1. 操作系统的主要功能包括：进程管理、内存管理、文件管理、设备管理。\n2. TCP三次握手过程：SYN -> SYN+ACK -> ACK\n3. HTTP状态码：200成功，404未找到，500服务器错误\n\n二、实践题（60分）\n设计了一个简单的学生管理系统，包含以下功能：\n- 学生信息的增删改查\n- 成绩录入和统计\n- 数据导出功能\n\n使用Spring Boot + MyBatis + MySQL实现。\"}', 164, 5, 22);
INSERT INTO `exam_submissions` VALUES (70, b'1', 77, '2025-11-28 15:27:26.463691', '考试成绩已发布', '{\"content\": \"这是我的考试答案。\n\n一、选择题答案：\n1. A  2. B  3. C  4. D  5. A\n6. B  7. C  8. A  9. D  10. B\n\n二、填空题答案：\n1. 数据结构\n2. 算法复杂度\n3. 二叉树\n4. 哈希表\n5. 递归\n\n三、简答题：\n1. 数据结构是计算机存储、组织数据的方式，它是指相互之间存在一种或多种特定关系的数据元素的集合。\n\n2. 时间复杂度是衡量算法执行时间随输入规模增长的变化趋势，常用大O表示法。\"}', 109, 5, 34);
INSERT INTO `exam_submissions` VALUES (71, b'1', 83, '2025-11-28 15:21:26.476631', '考试成绩已发布', '{\"content\": \"考试答案提交：\n\n第一部分 - 选择题（每题2分）\n1-5: ABCDA\n6-10: BCDAB\n\n第二部分 - 判断题（每题1分）\n1. 对  2. 错  3. 对  4. 对  5. 错\n\n第三部分 - 编程题\n```python\ndef bubble_sort(arr):\n    n = len(arr)\n    for i in range(n):\n        for j in range(0, n-i-1):\n            if arr[j] > arr[j+1]:\n                arr[j], arr[j+1] = arr[j+1], arr[j]\n    return arr\n```\n\n以上是我的全部答案。\"}', 112, 5, 38);
