INSERT INTO `exam_submissions` VALUES (290, b'1', 100, '2025-11-28 16:47:25.438158', '考试成绩良好', '{\"content\": \"这是我的考试答案。\n\n一、选择题答案：\n1. A  2. B  3. C  4. D  5. A\n6. B  7. C  8. A  9. D  10. B\n\n二、填空题答案：\n1. 数据结构\n2. 算法复杂度\n3. 二叉树\n4. 哈希表\n5. 递归\n\n三、简答题：\n1. 数据结构是计算机存储、组织数据的方式，它是指相互之间存在一种或多种特定关系的数据元素的集合。\n\n2. 时间复杂度是衡量算法执行时间随输入规模增长的变化趋势，常用大O表示法。\"}', 24, 8, 142);
INSERT INTO `exam_submissions` VALUES (291, b'1', 51, '2025-11-28 16:56:25.438158', '考试成绩良好', '{\"content\": \"考试答案提交：\n\n第一部分 - 选择题（每题2分）\n1-5: ABCDA\n6-10: BCDAB\n\n第二部分 - 判断题（每题1分）\n1. 对  2. 错  3. 对  4. 对  5. 错\n\n第三部分 - 编程题\n```python\ndef bubble_sort(arr):\n    n = len(arr)\n    for i in range(n):\n        for j in range(0, n-i-1):\n            if arr[j] > arr[j+1]:\n                arr[j], arr[j+1] = arr[j+1], arr[j]\n    return arr\n```\n\n以上是我的全部答案。\"}', 7, 8, 182);
INSERT INTO `exam_submissions` VALUES (292, b'1', 57, '2025-11-28 16:25:25.447193', '考试成绩良好', '{\"content\": \"期末考试答卷\n\n一、名词解释（20分）\n1. 栈：一种后进先出(LIFO)的数据结构\n2. 队列：一种先进先出(FIFO)的数据结构\n3. 链表：由节点组成的线性数据结构\n4. 图：由顶点和边组成的非线性数据结构\n\n二、计算题（30分）\n1. 二叉树遍历结果：\n   前序：A B D E C F\n   中序：D B E A F C\n   后序：D E B F C A\n\n三、论述题（50分）\n详细阐述了数据库索引的原理和优化策略...\"}', 66, 9, 7);
