INSERT INTO `exam_submissions` VALUES (432, b'0', NULL, '2025-12-21 16:13:45.000000', NULL, '{\"content\": \"期末考试答卷\n\n一、名词解释（20分）\n1. 栈：一种后进先出(LIFO)的数据结构\n2. 队列：一种先进先出(FIFO)的数据结构\n3. 链表：由节点组成的线性数据结构\n4. 图：由顶点和边组成的非线性数据结构\n\n二、计算题（30分）\n1. 二叉树遍历结果：\n   前序：A B D E C F\n   中序：D B E A F C\n   后序：D E B F C A\n\n三、论述题（50分）\n详细阐述了数据库索引的原理和优化策略...\"}', 150, 22, 10);
INSERT INTO `exam_submissions` VALUES (433, b'0', NULL, '2025-12-21 16:13:45.000000', NULL, '{\"content\": \"考试作答：\n\n【单选题】\n1.B 2.A 3.C 4.D 5.B 6.A 7.C 8.D 9.A 10.B\n\n【多选题】\n1.ABD 2.ACD 3.BC 4.ABCD 5.AD\n\n【简答题】\n1. 面向对象的三大特性：\n   - 封装：将数据和操作封装在类中\n   - 继承：子类继承父类的属性和方法\n   - 多态：同一接口的不同实现\n\n2. SQL优化方法：\n   - 使用索引\n   - 避免SELECT *\n   - 合理使用JOIN\"}', 150, 22, 11);
INSERT INTO `exam_submissions` VALUES (434, b'0', NULL, '2025-12-21 16:13:45.000000', NULL, '{\"content\": \"我的考试答案：\n\n一、基础知识（40分）\n1. 操作系统的主要功能包括：进程管理、内存管理、文件管理、设备管理。\n2. TCP三次握手过程：SYN -> SYN+ACK -> ACK\n3. HTTP状态码：200成功，404未找到，500服务器错误\n\n二、实践题（60分）\n设计了一个简单的学生管理系统，包含以下功能：\n- 学生信息的增删改查\n- 成绩录入和统计\n- 数据导出功能\n\n使用Spring Boot + MyBatis + MySQL实现。\"}', 180, 23, 12);
