INSERT INTO `exam_submissions` VALUES (462, b'0', 0, '2026-01-01 23:32:17.817000', NULL, '{\"content\": \"期末考试答卷\n\n一、名词解释（20分）\n1. 栈：一种后进先出(LIFO)的数据结构\n2. 队列：一种先进先出(FIFO)的数据结构\n3. 链表：由节点组成的线性数据结构\n4. 图：由顶点和边组成的非线性数据结构\n\n二、计算题（30分）\n1. 二叉树遍历结果：\n   前序：A B D E C F\n   中序：D B E A F C\n   后序：D E B F C A\n\n三、论述题（50分）\n详细阐述了数据库索引的原理和优化策略...\"}', 0, 43, 6);
