-- ----------------------------
-- Table structure for courses
-- ----------------------------
DROP TABLE IF EXISTS `courses`;
CREATE TABLE `courses`  (
  `id` bigint(0) NOT NULL AUTO_INCREMENT,
  `course_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '课程代码',
  `course_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `credit` int(0) NOT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `total_hours` smallint(0) NOT NULL DEFAULT 48 COMMENT '总学时',
  `teacher_id` bigint(0) NOT NULL,
  `assessment_method` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '考核方式',
  `create_time` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间',
  `update_time` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '更新时间',
  `course_director` bigint(0) NULL DEFAULT NULL COMMENT '课程负责人ID',
  `course_category` enum('必修','选修','公共课','专业课') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '必修' COMMENT '课程类别：必修、选修、公共课、专业课',
  `course_status` enum('未开始','进行中','已结束') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '未开始' COMMENT '课程状态：未开始、进行中、已结束',
  `semester` enum('第一学期','第二学期','暑期') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '开课学期：第一学期、第二学期、暑期',
  `start_date` date NULL DEFAULT NULL COMMENT '课程开始时间',
  `end_date` date NULL DEFAULT NULL COMMENT '课程结束时间',
  `max_students` int(0) NULL DEFAULT 100 COMMENT '最大学生数',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_course_code`(`course_code`) USING BTREE COMMENT '课程代码唯一索引',
  INDEX `FK_courses_director`(`course_director`) USING BTREE,
  INDEX `idx_courses_teacher_status`(`teacher_id`, `course_status`) USING BTREE,
  INDEX `idx_courses_search`(`course_name`, `course_category`, `course_status`) USING BTREE,
  INDEX `idx_courses_semester`(`semester`) USING BTREE,
  INDEX `idx_courses_start_end_date`(`start_date`, `end_date`) USING BTREE,
  INDEX `idx_courses_full_search`(`course_name`, `course_category`, `course_status`, `semester`, `credit`) USING BTREE,
  INDEX `idx_courses_course_code`(`course_code`) USING BTREE,
  CONSTRAINT `FK_courses_director` FOREIGN KEY (`course_director`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_courses_teacher` FOREIGN KEY (`teacher_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 58 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

