-- ----------------------------
-- View structure for v_course_classes
-- ----------------------------
DROP VIEW IF EXISTS `v_course_classes`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v_course_classes` AS select `cc`.`id` AS `id`,`cc`.`capacity` AS `capacity`,`cc`.`class_name` AS `class_name`,`cc`.`year` AS `year`,`cc`.`course_id` AS `course_id`,`cc`.`teacher_id` AS `teacher_id`,`cc`.`major_id` AS `major_id`,`cc`.`class_time` AS `class_time`,`cc`.`class_location` AS `class_location`,`cc`.`create_time` AS `create_time`,`cc`.`update_time` AS `update_time`,`c`.`course_name` AS `course_name`,`c`.`course_code` AS `course_code`,`c`.`course_category` AS `course_category`,`c`.`course_status` AS `course_status`,`m`.`major_name` AS `major_name`,`u`.`username` AS `teacher_name` from (((`course_classes` `cc` join `courses` `c` on((`cc`.`course_id` = `c`.`id`))) join `majors` `m` on((`cc`.`major_id` = `m`.`id`))) join `users` `u` on((`cc`.`teacher_id` = `u`.`id`)));

-- ----------------------------
-- Procedure structure for sp_get_course_info
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_get_course_info`;
delimiter ;;
CREATE PROCEDURE `sp_get_course_info`(IN p_course_id bigint)
BEGIN
    SELECT c.*, u.username as teacher_name, d.username as director_name
    FROM courses c
    LEFT JOIN users u ON c.teacher_id = u.id
    LEFT JOIN users d ON c.course_director = d.id
    WHERE c.id = p_course_id;
END
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
